import { chunk } from "lodash-es";
export default function (wf) {
  const groups = chunk([1, 2, 3, 4, 5], 2);
  wf.setState("groups", groups);
  return groups;
}

import { flatten } from "lodash-es";
export default function (wf) {
  return { items: flatten(wf.getState("groups")).length, prior: wf.getReturn("split") };
}
